/**
 * P4e (coordinator, 2026-11-05): a typed ko-vi answer whose key is in 해요체 also accepts the same sentence in 합쇼체
 * (가요 → 갑니다, 학생이에요 → 학생입니다, 갈 거예요 → 갈 겁니다, 조심하세요 → 조심하십시오). It is correct, only more
 * formal, so it is never marked wrong. The renderings are generated by content/ko/_drafts/_generators/ko_text.py
 * (_formal_forms); this test reads the course pack (staged until promote) and compares through the ko rules' lenient
 * form, as the grader does.
 */
import { describe, expect, test } from "bun:test";
import { existsSync } from "fs";

import { readJson } from "../lib/pipeline";
import { createKoreanRules } from "../../src/lib/languages/ko";

const STAGED = "content/ko/_drafts/staged/content/courses/ko-vi.json";
const PACK = existsSync(STAGED) ? STAGED : "content/courses/ko-vi.json";
type TypeAnswer = { id: string; type: "typeAnswer"; prompt: string; answer: string; alternatives: string[] };
const typed = (): TypeAnswer[] =>
  (readJson(PACK) as { sections: { units: { lessons: { exercises: { type: string }[] }[] }[] }[] }).sections
    .flatMap((s) => s.units.flatMap((u) => u.lessons.flatMap((l) => l.exercises)))
    .filter((e): e is TypeAnswer => e.type === "typeAnswer");

const rules = createKoreanRules();
const accepts = (e: TypeAnswer, attempt: string) =>
  [e.answer, ...e.alternatives].some((k) => rules.normalizeLenientAlternate!(k) === rules.normalizeLenientAlternate!(attempt));

describe("ko-vi typed answers accept the 합니다 form of a 해요 key", () => {
  test.skipIf(!existsSync(PACK))("known keys", () => {
    const byAnswer = new Map(typed().map((e) => [e.answer, e]));
    const cases: [string, string][] = [
      ["회사에 가요.", "회사에 갑니다."],
      ["공장에서 일해요.", "공장에서 일합니다."],
      ["저는 학생이에요.", "저는 학생입니다."],
      ["어제 병원에 갔어요.", "어제 병원에 갔습니다."],
      ["조심하세요.", "조심하십시오."],
      ["다음 주에 쉴 거예요.", "다음 주에 쉴 겁니다."],
      ["열쇠가 있어요?", "열쇠가 있습니까?"],
      ["저는 학생이 아니에요.", "저는 학생이 아닙니다."],
    ];
    for (const [key, formal] of cases) {
      const e = byAnswer.get(key);
      expect(e, key).toBeDefined();
      expect(accepts(e!, formal), `${key} → ${formal}`).toBe(true);
    }
  });

  test.skipIf(!existsSync(PACK))("every key ending in a 해요 sentence lists a 합쇼체 rendering, unless the prompt asks for the familiar style", () => {
    const missing = typed()
      .filter((e) => /요[.?!]?$/.test(e.answer.trim()) && !e.prompt.includes("thân mật"))
      .filter((e) => !e.alternatives.some((a) => /(니다|니까|시오)[.?!]?$/.test(a.trim())))
      .map((e) => `${e.id}: ${e.answer}`);
    expect(missing).toEqual([]);
  });
});
